import{_ as t,o,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Products Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Products Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/products-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Products Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/products-overview"}]]},"headers":[],"relativePath":"user-guide/products-overview.md","filePath":"user-guide/products-overview.md","lastUpdated":1786636213000}'),d={name:"user-guide/products-overview.md"};function s(c,e,n,i,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="products-module" tabindex="-1">Products Module <a class="header-anchor" href="#products-module" aria-label="Permalink to &quot;Products Module&quot;">​</a></h1><p>Phase 5 Inventory module on the frozen platform. Products is the tenant catalog for goods and services, used by Inventory and optionally by Purchase Order lines.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Workspace users</td><td><a href="/user-guide/products">products.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/products">products-developer.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/products">products-production.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-products">tenant-v1-products.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Catalog for goods and services (SKU, name, category, description, unit, cost, price, currency, status, stock-tracking)</li><li>Turn off <strong>Track stock</strong> for services and non-stocked goods; Inventory only manages tracked items</li><li>Currency picker uses the shared workspace currency list and defaults to the tenant currency</li><li>Product categories managed in the same module</li><li>Search, status/category filters, KPI summary, soft delete, restore, and permanent deletion</li><li>Notes and activity timeline</li><li>Optional <code>product_id</code> on Purchase Order lines</li><li>Inventory uses stock-tracked products through its required Products dependency</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>products.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code></p><p>Enable Products from Marketplace (free). Catalog: <code>products</code>, category <code>inventory</code> (<strong>Inventory</strong>, sort <code>50</code>), <code>is_default_included = false</code>, <code>is_billable = false</code>, module sort <code>10</code>.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><p>Products defines catalog information only. It does not itself mutate stock. Use the <a href="/user-guide/inventory-overview">Inventory</a> module for stock levels, adjustments, receipts, and transfers.</p><p>Serial numbers, lots, and COGS are not part of Phase 5.</p>',12)])])}const h=t